Method.Source:
    /// <summary>
    /// CehckInvoice method extension
    /// </summary>
    /// <param name = "_ledgerJournalTrans"><c>LedgerJournalTrans</c> buffer.</param>
    /// <returns>True if invoice is not found; otherwise false</returns>
    boolean checkInvoice(LedgerJournalTrans _ledgerJournalTrans)
    {
        // <GTH>
        boolean ret;
        VendTable metVendTable;
        // </GTH>

        ret = next checkInvoice(_ledgerJournalTrans);

        if (VendParameters::find().CheckInvoice == ReuseVoucher::METInvoiceValidation)
        {
            metvendTable = VendTable::findByLedgerDimension(_ledgerJournalTrans.LedgerDimension);

            ret  = metvendTable.metCheckInvoice(_ledgerJournalTrans.Invoice,
                                                _ledgerJournalTrans.DocumentDate,
                                                _ledgerJournalTrans.CurrencyCode,
                                                abs(_ledgerJournalTrans.amount()));
        }
        
        return ret;
    }
